using System.Collections; using UnityEngine; using UnityEngine.AI; namespace MyLumo { [RequireComponent(typeof(NavMeshAgent))] public class LumoController:MonoBehaviour { public NavMeshAgent agent; public LumoAnimatorBridge animationBridge; public LumoNeeds needs; public LumoInventory inventory; public LumoLocation currentLocation=LumoLocation.Home; public float interactionDuration=3.5f; void Awake(){if(!agent)agent=GetComponent<NavMeshAgent>();} void Update(){if(animationBridge&&agent)animationBridge.SetMoveSpeed(agent.velocity.magnitude);} public IEnumerator ExecuteTask(LumoTask t){var a=WorldRegistry.Instance?WorldRegistry.Instance.FindFor(t.location,t.action,t.targetId):null;if(a&&agent&&agent.isOnNavMesh){agent.SetDestination(a.Position);while(agent.pathPending)yield return null;while(agent.remainingDistance>Mathf.Max(agent.stoppingDistance+.08f,.2f))yield return null;transform.rotation=a.Rotation;currentLocation=t.location;}else if(t.action==LumoActionType.Move)currentLocation=t.location;if(t.action!=LumoActionType.Move&&t.action!=LumoActionType.None){animationBridge?.Trigger(t.action);Apply(t);yield return new WaitForSeconds(interactionDuration);}} void Apply(LumoTask t){switch(t.action){case LumoActionType.Eat:needs?.AteMeal();break;case LumoActionType.Sleep:needs?.Slept();break;case LumoActionType.Dance:needs?.Danced();break;case LumoActionType.PetAnimal:needs?.Socialized();break;case LumoActionType.Dress:if(!string.IsNullOrWhiteSpace(t.itemId))inventory?.EquipHat(t.itemId);break;case LumoActionType.PlayGuitar:inventory?.Add("guitar");break;case LumoActionType.EnterCar:inventory?.Add("car");break;}} } }
